INSERT INTO public.products (id, category_id, name, description, price, weight, pieces, image, images, badge, ingredients, nutrition, is_available) VALUES ('burger-salmon', 'sushi-burgery', '{"pl":"Salmon Burger","uk":"Салмон Бургер"}'::jsonb, '{"pl":"Chrupiący sushi burger w złocistej tempurze ze świeżym łososiem, awokado, ogórkiem, serkiem śmietankowym, sosem unagi i prażonym sezamem.","uk":"Хрусткий гарячий суші бургер у темпурі зі свіжим лососем, авокадо, свіжим огірком, ніжним крем-сиром, соусом унагі та кунжутом."}'::jsonb, 55, 320, 1, '', '[]'::jsonb, NULL, '{"pl":["NORI","RYŻ","ŁOSOŚ","AWOKADO","OGÓREK","SER ŚMIETANKOWY","SOS UNAGI","SEZAM","TEMPURA"],"uk":["НОРІ","РИС","ЛОСОСЬ","АВОКАДО","ОГІРОК","ВЕРШКОВИЙ СИР","СОУС УНАГІ","КУНЖУТ","ТЕМПУРА"]}'::jsonb, '{"calories":460,"proteins":18.5,"fats":18.2,"carbs":52}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price, weight = EXCLUDED.weight, pieces = EXCLUDED.pieces, badge = EXCLUDED.badge, ingredients = EXCLUDED.ingredients;
INSERT INTO public.products (id, category_id, name, description, price, weight, pieces, image, images, badge, ingredients, nutrition, is_available) VALUES ('burger-tuna', 'sushi-burgery', '{"pl":"Tuna Burger","uk":"Туна Бургер"}'::jsonb, '{"pl":"Wyrazisty sushi burger z tuńczykiem, dojrzałym awokado, ogórkiem, serkiem, ostrym sosem sriracha mayo, sezamem i sosem teriyaki w tempurze.","uk":"Пікантний суші бургер з океанічним тунцем, авокадо, огірком, крем-сиром, соусом шрірача майо, кунжутом та соусом теріякі в темпурі."}'::jsonb, 55, 320, 1, '', '[]'::jsonb, NULL, '{"pl":["NORI","RYŻ","TUŃCZYK","AWOKADO","OGÓREK","SER ŚMIETANKOWY","SOS SRIRACHA MAYO","SEZAM","SOS TERIYAKI","TEMPURA"],"uk":["НОРІ","РИС","ТУНЕЦЬ","АВОКАДО","ОГІРОК","ВЕРШКОВИЙ СИР","СОУС ШРІРАЧА МАЙО","КУНЖУТ","СОУС ТЕРІЯКІ","ТЕМПУРА"]}'::jsonb, '{"calories":450,"proteins":19.5,"fats":17,"carbs":51.5}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price, weight = EXCLUDED.weight, pieces = EXCLUDED.pieces, badge = EXCLUDED.badge, ingredients = EXCLUDED.ingredients;
INSERT INTO public.products (id, category_id, name, description, price, weight, pieces, image, images, badge, ingredients, nutrition, is_available) VALUES ('burger-morski', 'sushi-burgery', '{"pl":"Morski Burger","uk":"Морський Бургер"}'::jsonb, '{"pl":"Bogaty burger z krewetkami, krabstikami surimi, chrupiącym ogórkiem, mango, sosem mango jalapeno i chrupiącymi płatkami migdałowymi.","uk":"Вишуканий морський бургер із ніжними креветками, сурімі, свіжим огірком, солодким манго, соусом манго-халапеньйо та пелюстками мигдалю."}'::jsonb, 52, 310, 1, '', '[]'::jsonb, NULL, '{"pl":["NORI","RYŻ","KREWETKI","KRABSTIKI SURIMI","OGÓREK","MANGO","SOS MANGO JALAPENO","PŁATKI MIGDAŁOWE","TEMPURA"],"uk":["НОРІ","РИС","КРЕВЕТКИ","КРАБОВІ ПАЛИЧКИ СУРІМІ","ОГІРОК","МАНГО","СОУС МАНГО ХАЛАПЕНЬЙО","ПЕЛЮСТКИ МИГДАЛЮ","ТЕМПУРА"]}'::jsonb, '{"calories":435,"proteins":16.5,"fats":15.8,"carbs":54}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price, weight = EXCLUDED.weight, pieces = EXCLUDED.pieces, badge = EXCLUDED.badge, ingredients = EXCLUDED.ingredients;
