INSERT INTO public.products (id, category_id, name, description, price, weight, pieces, image, images, badge, ingredients, nutrition, is_available) VALUES ('poke-losos', 'poke-bowl', '{"pl":"Poke Bowl z Łososiem","uk":"Поке Боул з Лососем"}'::jsonb, '{"pl":"Świeży łosoś na puszystym ryżu z awokado, algami wakame, soczystym mango, kukurydzą, soją edamame, sosem ponzu, sosem teriyaki i sezamem.","uk":"Свіжий філе-лосось на подушці з рису з авокадо, водоростями вакаме, соковитим манго, кукурудзою, бобами едамаме, соусом понзу, теріякі та кунжутом."}'::jsonb, 43, 380, 1, '', '[]'::jsonb, NULL, '{"pl":["RYŻ","NORI","AWOKADO","WAKAME","MANGO","KUKURYDZA","ŁOSOŚ","SOJA EDAMAME","SOS PONZU","SOS TERIYAKI","SEZAM"],"uk":["РИС","НОРІ","АВОКАДО","ВАКАМЕ","МАНГО","КУКУРУДЗА","ЛОСОСЬ","СОЯ ЕДАМАМЕ","СОУС ПОНЗУ","СОУС ТЕРІЯКІ","КУНЖУТ"]}'::jsonb, '{"calories":460,"proteins":21,"fats":14.5,"carbs":62}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price, weight = EXCLUDED.weight, pieces = EXCLUDED.pieces, badge = EXCLUDED.badge, ingredients = EXCLUDED.ingredients;
